import pytest
from unittest.mock import patch, Mock
from scanners.docker_scanner import DockerScanner
from scanners.k8s_scanner import K8sScanner
from scanners.repo_scanner import RepoScanner

@patch('subprocess.check_output')
def test_docker_scanner(mock_check_output):
    mock_check_output.side_effect = [
        "container1\ncontainer2",
        "image1:tag1\nimage2:tag2"
    ]
    scanner = DockerScanner()
    results = scanner.scan()
    assert len(results) == 4
    assert any(r['type'] == 'docker_container' and r['name'] == 'container1' for r in results)
    assert any(r['type'] == 'docker_image' and r['name'] == 'image1:tag1' for r in results)

@patch('subprocess.check_output')
def test_k8s_scanner(mock_check_output):
    mock_check_output.side_effect = [
        "ns1 pod1 ns2 pod2",
        "ns1 svc1 ns2 svc2"
    ]
    scanner = K8sScanner()
    results = scanner.scan()
    assert len(results) == 4
    assert any(r['type'] == 'k8s_pod' and r['name'] == 'pod1' and r['location'] == 'ns1' for r in results)
    assert any(r['type'] == 'k8s_service' and r['name'] == 'svc2' and r['location'] == 'ns2' for r in results)

@patch('os.walk')
def test_repo_scanner(mock_walk):
    mock_walk.return_value = [("/project", [".git"], [])]
    scanner = RepoScanner()
    results = scanner.scan()
    assert len(results) == 1
    assert results[0]['type'] == 'git_repo'
    assert results[0]['name'] == 'project'
    assert results[0]['location'] == 'project'

